CREATE OR REPLACE FUNCTION public.generate_restaurant_payout_invoice(p_restaurant_id uuid, p_month date DEFAULT NULL::date)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
  target_month date;
  period_s date;
  period_e date;
  ext_period record;
  inv_count integer := 0;
  next_num integer;
  rev numeric;
  za_rev numeric;
  tva_rate numeric := 0.077;
BEGIN
  -- Si p_month est null, on prend le mois dernier complet, sinon le mois demandé.
  target_month := COALESCE(p_month::date, (date_trunc('month', now()) - interval '1 month')::date);
  period_s := date_trunc('month', target_month)::date;
  period_e := (period_s + interval '1 month' - interval '1 day')::date;

  -- Vérif si déjà facturé
  IF EXISTS (
    SELECT 1
    FROM restaurant_invoices
    WHERE restaurant_id = p_restaurant_id
      AND period_start = period_s
      AND period_end = period_e
  ) THEN
    RETURN 0;
  END IF;

  -- "encaissement Tok": Les commandes standard.
  -- On recalcule le montant brut en ajoutant les Miamz (points_discount_amount) si présents.
  -- Car Tok encaisse le total, et prend en charge les Miamz. Le restaurant récupère 90% de : (Paiement client + Miamz).
  SELECT COALESCE(SUM(total_amount + COALESCE((metadata->>'points_discount_amount')::numeric, 0)), 0) INTO rev
  FROM orders
  WHERE restaurant_id = p_restaurant_id
    AND lower(COALESCE(status, '')) NOT IN ('cancelled', 'refused', 'payment_failed')
    AND created_at >= period_s::timestamptz
    AND created_at < (period_e + interval '1 day')::timestamptz;

  -- Ventes zero-attente (Réservations, sans miamz car pas dispo dessus pour l'instant)
  SELECT COALESCE(SUM(total_amount), 0) INTO za_rev
  FROM reservations
  WHERE restaurant_id = p_restaurant_id
    AND lower(COALESCE(feature, '')) = 'zero-attente'
    AND lower(COALESCE(status, '')) NOT IN ('cancelled', 'no_show')
    AND total_amount > 0
    AND date >= period_s
    AND date <= period_e;

  rev := rev + za_rev;

  -- Le restaurant facture Tok pour 90% de ce total brut
  rev := rev * 0.90;

  IF rev > 0 THEN
    SELECT COALESCE(MAX(CAST(SUBSTRING(invoice_number FROM '[0-9]+$') AS integer)), 0) + 1
    INTO next_num
    FROM restaurant_invoices
    WHERE restaurant_id = p_restaurant_id;

    INSERT INTO restaurant_invoices (
      restaurant_id,
      period_start,
      period_end,
      amount_ht,
      amount_tva,
      amount_ttc,
      status,
      invoice_number,
      due_at
    )
    VALUES (
      p_restaurant_id,
      period_s,
      period_e,
      ROUND(rev / (1 + tva_rate), 2),
      ROUND(rev - rev / (1 + tva_rate), 2),
      ROUND(rev, 2),
      'draft', -- Draft so they can preview it, or 'pending' meaning Tok owes them.
      'FAC-' || TO_CHAR(period_s, 'YYYYMM') || '-' || LPAD(next_num::text, 4, '0'),
      (period_e + interval '30 days')::timestamptz
    );
    inv_count := 1;
  END IF;

  RETURN inv_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_restaurant_payout_invoice(p_restaurant_id uuid, p_month text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  inv_id uuid;
  next_num integer;
  rev numeric := 0;
  za_rev numeric := 0;
  tva_rate numeric := 0.077;
  unpaid_orders_count integer := 0;
  unpaid_reservations_count integer := 0;
  min_date timestamptz;
  max_date timestamptz;
  inv_period_s date;
  inv_period_e date;
BEGIN
  SELECT COUNT(id), COALESCE(SUM(total_amount + COALESCE((metadata->>'points_discount_amount')::numeric, 0)), 0), MIN(created_at), MAX(created_at)
  INTO unpaid_orders_count, rev, min_date, max_date
  FROM orders
  WHERE restaurant_id = p_restaurant_id
    AND restaurant_invoice_id IS NULL
    AND lower(COALESCE(status, '')) NOT IN ('cancelled', 'refused', 'payment_failed', 'pending');

  SELECT COUNT(id), COALESCE(SUM(total_amount), 0), LEAST(min_date, MIN(created_at)), GREATEST(max_date, MAX(created_at))
  INTO unpaid_reservations_count, za_rev, min_date, max_date
  FROM reservations
  WHERE restaurant_id = p_restaurant_id
    AND restaurant_invoice_id IS NULL
    AND lower(COALESCE(feature, '')) = 'zero-attente'
    AND lower(COALESCE(status, '')) NOT IN ('cancelled', 'no_show', 'pending')
    AND total_amount > 0;

  IF unpaid_orders_count = 0 AND unpaid_reservations_count = 0 THEN
    RETURN 0;
  END IF;

  rev := rev + za_rev;
  rev := rev * 0.90;

  inv_period_s := COALESCE(min_date::date, CURRENT_DATE);
  inv_period_e := COALESCE(max_date::date, CURRENT_DATE);

  SELECT COALESCE(MAX(CAST(SUBSTRING(invoice_number FROM '[0-9]+$') AS integer)), 0) + 1
  INTO next_num
  FROM restaurant_invoices
  WHERE restaurant_id = p_restaurant_id;

  INSERT INTO restaurant_invoices (
    restaurant_id,
    period_start,
    period_end,
    amount_ht,
    amount_tva,
    amount_ttc,
    status,
    invoice_number,
    due_at
  )
  VALUES (
    p_restaurant_id,
    inv_period_s,
    inv_period_e,
    ROUND(rev / (1 + tva_rate), 2),
    ROUND(rev - rev / (1 + tva_rate), 2),
    ROUND(rev, 2),
    'pending',
    'FAC-' || TO_CHAR(CURRENT_DATE, 'YYYYMM') || '-' || LPAD(next_num::text, 4, '0'),
    (CURRENT_DATE + interval '30 days')::timestamptz
  ) RETURNING id INTO inv_id;

  UPDATE orders
  SET restaurant_invoice_id = inv_id
  WHERE restaurant_id = p_restaurant_id
    AND restaurant_invoice_id IS NULL
    AND lower(COALESCE(status, '')) NOT IN ('cancelled', 'refused', 'payment_failed', 'pending');

  UPDATE reservations
  SET restaurant_invoice_id = inv_id
  WHERE restaurant_id = p_restaurant_id
    AND restaurant_invoice_id IS NULL
    AND lower(COALESCE(feature, '')) = 'zero-attente'
    AND lower(COALESCE(status, '')) NOT IN ('cancelled', 'no_show', 'pending')
    AND total_amount > 0;

  RETURN 1;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_restaurant_recommendations(p_restaurant_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  result json;
  v_actor_id uuid := auth.uid();
  v_is_service_role boolean := auth.role() = 'service_role';
BEGIN
  IF NOT v_is_service_role AND NOT public.has_role(v_actor_id, 'admin') AND NOT EXISTS (
    SELECT 1
    FROM public.restaurants
    WHERE id = p_restaurant_id
      AND owner_id = v_actor_id
  ) THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  SELECT COALESCE(json_agg(row_to_json(r)), '[]'::json)
  INTO result
  FROM (
    SELECT *
    FROM public.restaurant_recommendations
    WHERE restaurant_id = p_restaurant_id
      AND status = 'pending'
    ORDER BY priority ASC
    LIMIT 10
  ) r;

  RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.redeem_loyalty_points(user_id_param uuid, points_to_redeem integer, description_param text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_current_points integer;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF user_id_param IS DISTINCT FROM v_actor_id THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  IF COALESCE(points_to_redeem, 0) <= 0 THEN
    RAISE EXCEPTION 'points_to_redeem must be positive';
  END IF;

  SELECT loyalty_points
  INTO v_current_points
  FROM public.profiles
  WHERE user_id = v_actor_id
  FOR UPDATE;

  IF v_current_points IS NULL OR v_current_points < points_to_redeem THEN
    RETURN false;
  END IF;

  UPDATE public.profiles
  SET loyalty_points = loyalty_points - points_to_redeem
  WHERE user_id = v_actor_id;

  INSERT INTO public.loyalty_transactions (
    user_id,
    amount,
    transaction_type,
    description
  )
  VALUES (
    v_actor_id,
    -points_to_redeem,
    'redeem',
    description_param
  );

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$
